function tradeWorldCanvas(config, state, running) {
  const world = state.tradeWorld;
  if (!world || !config.tradeWorld) return void 0;
  return {
    tick: world.tick,
    running,
    freight: world.shipments.flatMap((shipment) => {
      const spec = config.tradeWorld.shipments.find((item) => item.id === shipment.id);
      if (!spec) return [];
      const progress = Math.max(0, Math.min(1, shipment.progressTicks / spec.travelTicks));
      return [
        {
          id: shipment.id,
          name: spec.name,
          routeId: shipment.routeId,
          progress: shipment.direction === "return" ? 1 - progress : progress,
          deliveries: shipment.deliveries
        }
      ];
    }),
    conditions: world.effects.flatMap(
      (effect2) => effect2.kind === "shipment" ? [] : [
        {
          id: effect2.id,
          kind: effect2.kind,
          locations: config.locations.filter((location) => effect2.locationIds.includes(location.id)).map((location) => ({ x: location.mapX, y: location.mapY }))
        }
      ]
    )
  };
}

